INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','قياس منتوجية القطن حسب الهيكتار بطريقة شريط التيب: دليل عملي للمزارع العراقي' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على كيفية حساب حصاد القطن للهيكتار بدقة باستخدام تقنية شريط التيب، مع نصائح عملية موجهة لفهم العوامل الفنية المؤثرة على المحصول.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
