INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Рӯйхати муфассал оид ба ҳисоби фазои пашу ба ҳар ҳектар бо истифода аз усули нобаи типӣ. Маслиҳатҳои амалӣ барои кӯҳнарони кӯҳна. Бидуни иловаҳои зиёдатӣ.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
