INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Чаро барои парвариши нӯк лойи пайпӣ интихоб ме‌шуд?</h2>\n<p>Худи нӯк (Pisum sativum) як наботи аст, ки решаҳои он дар чуқурии камтари хок ҷойгир шудаанд ва дар марҳилаҳои ҳассос ба монанди гулу бугъу гулгаштӣ ҳассосияти баланди ба шиддати хушкӣ дорад. Истифодаи <strong>обёрӣи лойи пайпӣ</strong> ба ҷои обёрӣи қатрагӣи анъанавӣ ё обкунӣ, боиси мешавад, ки об бевосита дар ширини бари зери сатҳи хок (дар чуқурии решаҳои фаъол) расонида шавад. Ин на танҳо зиёни бухоршавиро ба ҳадди ақал мерасонад, балки боиси устуворишадани намӣ дар минтақаи ризофшора (Rizosphere) мешавад, ки афзоиши решаҳоро меистисорад.</p>\n<p>Яке аз муҳимтарин бенобҳои ин система кам шудани ниёз ба замин кардани такрорӣ аст, зеро лойҳои пайпӣ одатан аз пластики бозикторӣшаванда ё вайроншаванда месозанд ва бевосита дар сатҳҳои кишт ҷойгир карда мешаванд. Барои фаҳмиши беҳтари сохтори физикии ин хатҳо, метавонед ба хосиятҳои лойи пайпӣ ва сифатҳояш таваҷҷуҳ диҳед, то аз намуди материҳо ва ғафсии мавҷуда огоҳ шавед.</p>\n\n\n\n<h2>омилҳои асосии таъсиррасонанда ба ҳаҷми нӯк</h2>\n<p>Бисёр деҳқонон меёнд, ки танҳо об муҳим аст, вале ҳақиқат ин аст, ки ҳосили нӯки (ҳосил) натиҷаи мураккаби бисёр тағйирёбандаҳост. Дар киштҳои муосир, се даври асосӣ барои омода кардани замин, идоракунии намии кишоварзӣ ва мубориа бо зараррасонҳо мавҷуд аст. Агар намии замин дар фосилаи байни решаҳо наҳомоген бошад, дарахтҳои нӯк дарами стресс қарор мегиранд ва шумораи буттаҳо кам мешавад.</p>\n<ul>\n<li><strong>Зичии бунёд:</strong> Ододда 12 то 15 кг бех дар як hectare тавсия мегардад. Гарчанде, ки ин миқдор вобаста ба шароити бех ва минтақа аст, вале зичии мувофиқ сабаб мешавад, ки рақобати нур ва об ба таври оптималӣ бошад.</li>\n<li><strong>Фосилаи сатҳҳо:</strong> Дар системаи рӣшакӣ (nobar), фосилаи байни сатҳҳои рӣша бояд дақиқ бо нақши калонпӯлӣ мувофиқат кунад, то ки ягон нохӯрдагии рӯянақон (пӯл) ҳосил намонад.</li>\n<li><strong>Мудирити ғизоёбӣ:</strong> Нуход баҳодиҳандаш аз муайянкунии нитроген дар занзираҳои решаистифода мекунад, вале дар марҳилаҳои аввали калонпӯлӣ, истифодаи қаторноги фосфорӣ дар канори сатҳи рӣша метавонад сабаби суръати баланди рушди вегетативӣ гардад.</li>\n</ul>\n\n<p>Барои муқоисаи ҳосилияти нуход бо дигар нобиҳанҷонҳо дар шароити монанд, омӯзиши миқдори бехи кду дар як hectare метавонад комёӣ бошад, зеро аз ҷиҳати идоракунии бодамӣ дар атрофи реша нуқтаҳои муштарок бо калонпӯлӣ нуход дорад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-نخود-در-هکتار-با-نوار-تیپ-تصویر-شاخص.webp" alt="میزان برداشت نخود در هکتار با نوار تیپ - تصویر 1"/><figcaption>crop yield per hectare drip irrigation нуход</figcaption></figure>\n\n<h2>Ҷадвали тайидгарӣ барои обёрӣ бо нобар дар нуход</h2>\n<p>Дар системаи қатрони ғойда шумо бо фишори паст ва доимӣ рӯбарӯед. Бинобар ин, овароиш бояд мунтазам ва дар фосилаҳои муайяни вақт анҷом дода шавад. Зери доираҳои реша об оҳиста шинонда мешавад. Дар пай оварда шудани як барномаи тавсияшуда барои минтақаи мулоим мебошад:</p>\n<table>\n<thead>\n<tr>\n<th>Марҳилаи афзоиш</th>\n<th>Талаботи оварош (литр дар як метри хат)</th>\n<th>Шумораи маротибаҳо дар ҳафта</th>\n<th>Ёддошти муҳим</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Бӯм</td>\n<td>Паст (нигоҳ доштани намнокӣ-и максималӣ)</td>\n<td>2 то 3</td>\n<td>Аз обори бузург пешгирӣ кардан то муҳаккамоти решаҳо</td>\n</tr>\n<tr>\n<td>Рӯшӣи вегетативӣ</td>\n<td>Миёна</td>\n<td>3 то 4</td>\n<td>Афзоиши тадриҷии ҳаҷми об</td>\n</tr>\n<tr>\n<td>Гулдодӣ ва мевагирӣ</td>\n<td>Зиёд (ҳассос ба хушкӣ)</td>\n<td>4 то 5</td>\n<td>Қутиқ кардани об дар ин марҳила ба рондани гулҳо оварда мерасонад</td>\n</tr>\n<tr>\n<td>Пухмон</td>\n<td>Кам шудани тадриҷӣ</td>\n<td>1 то 2</td>\n<td>Кам кардани оббарӣ барои мустаҳкам шудани дона ва пешгирии афзоиши шарбат</td>\n</tr>\n</tbody>\n</table>\n\n<p>Дар хотон доред, ки ҷадвали боло рамзи умумӣ аст. Дар минтаҳои бо хокҳои шағол, борабораи оббӯрӣ бояд бештар ва ҳаҷми ҳар маротиба камтар бошад. Барои пайдо кардани маълумоти дақиқтар дар бораи фосилаҳо ва сохтори хатҳо, мо пешниҳод мекунем, ки пайвастгиҳои навиши иригасиявиро санҷед, то аз саломатии система мутмаин шавед.</p>\n\n\n\n<h2>Маслиҳатҳои амалӣ барои зиёд кардани сифат ва миқдори гулҳо</h2>\n<p>Афзоиш <strong>Миқдори ҳосили нуҳур дар ҳектар бо усули наварӣ</strong> Бе диққат ба шлӯзӣ (стресс) ғайриимкон аст. Яке аз мушкилоти мӯътоде дар кунҷи нуҳур, хоби думбаргҳо аст, ки дар ҳолати рушди номувофиқи думбаргҳо аз сабаби номутобиқии намнокӣ ҳосил мешавад. Барои пешгирии ин мушкилӣ:</p>\n<ol>\n<li><strong>Истифодаи сими таҳкимкунанда (Staking):</strong> Агар зичии кунҷи баланд бошад, истифодаи сими кашиш ё сутунҳои хурд дар назди навари наварӣ метавонад аз хобидани думбаргҳо пешгирӣ кунад.</li>\n<li><strong>Назорати намнокии хок:</strong> Аз ҳисобкунакҳои намнокӣ истифода баред. Дар системаи наварӣ, шумо наметавонед намнокӣ-ро бо чашми ошкор ҳукм кунед. Намнокӣ бояд дар чуқурӣ аз 15 то 20 см устувор бошад.</li>\n<li><strong>Нобудсозии наварҳои иловагӣ:</strong> Агар фазои кофӣ дошта бошед, кам кардани фосилаи байни хатҳои наварӣ то 40 то 50 см метавонад соҳаи зери муҳосбати намнокӣ-ро зиёд кунад.</li>\n</ol>\n\n<p>Инчунин, диққат ба сифати ҷавдор ва антибактериалӣ кардани хок пеш аз партофтан мавҷӯдшавии бемориҳои зангорӣ, ки дар муҳитҳои тар бо парчамҳои чаръӣ бештар мушоҳида мешаванд, -ро кам мекунад. Барои партовҳои зич, омӯзиши миқоми ҷавдори чаръ дар як гектар метавонад дар фаҳмидани зичии хуби партовҳои донӣ кӯмак кунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-نخود-در-هکتار-با-نوار-تیپ-کاربرد-عملی.webp" alt="میزان برداشت نخود در هکتار با نوار تیپ - تصویر 2"/><figcaption>crop yield per hectare drip irrigation نخود</figcaption></figure>\n\n<h2>Чалҳои муқаррарӣ ва ҳалли онҳо</h2>\n<p>Яке аз чалҳои калонтарон дар истифодаи парчамҳои чаръӣ, сӯрох ё интиқол дохтан хатҳо аз ҷониби ҳайвоноти хурд ё мошинҳо аст. Барои ҳалли ин мушкил, баъзе деҳқонон аз парчамҳои чаръии бо сифати баландтар истифода мебаранд ё аз тӯриҳо муҳофизати сабук истифода мебаранд. Ҳамчунин, дарёфт шудани нӯкҳои парчамҳои чаръӣ ҳангоми истифода аз манбаъҳои обӣ бо зарраҳои муаллақ, аз дигар мушкилҳо аст. Фильтркардани мувофиқ (матол ва диск) лозим аст.</p>\n<p>Агар мувоҷеҳ шуд, ки рахиҳои шумо сабзӣ (хлорофи) нишон медиҳанд, метавонад оби ороишгирии шумо намехшавии баланд дошта бошад. Дар ин ҳолат, бояд ба шустани хок диққат диҳед. Барои фаҳмиши беҳтари рафтори намехшавӣ дар системаҳои гуногун, омӯзиши ороишгарии барғумон (ғизоӣ) ва шарифатҳо муфид аст.</p>\n\n\n\n<h2>Саволҳои муқаррарӣ (FAQ)</h2>\n<p><strong>1. Оё парчами чаръӣ барои нуқуди зудбаромад мувофиқ аст?</strong>\nБале, бо шароите, ки системаи гармкунанда ё пӯшонишҳои пистикӣ (тинг) дар паҳлӯи парчами чаръӣ истифода шаванд, то ҳарорати решаҳо дар фасли салқин нигоҳ дошта шавад.</p>\n<p><strong>2. Чанд сол аз як навори чистаро истифода бардӣ?</strong>\nВобаста ба навъ, оддӣ наворҳои чистаро 1 то 3 фасл устуворӣ мекунанд. Дар ҳама ҳол, тозакунии солонаи дохили наворт бо фишори об зарур аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-نخود-در-هکتار-با-نوار-تیپ-جزئیات-فنی.webp" alt="میزان برداشت نخود در هکتار با نوار تیپ - تصویر 3"/><figcaption>ҳосили парвариш дар ҳектар иригтсияи чистаро нӯхӯд</figcaption></figure>\n<p><strong>3. Оё дар нӯхӯд ниёз ба обдорӣ тавассути беракиш (фолат) доред?</strong>\nНӯхӯд обдориро тавассути беракиш (фолат) барои таъмиқдиҳии нитрогени ҳалшуда истифода намебарад, зеро ин растани аз сабти нитрогени ҳавоӣ тавассути решаҳо истифода мебарад. Аммо фосфор ва калий тавассути беракиш беҳтар ҷаббида мешаванд.</p>\n\n<h2>Хулоса</h2>\n<p>Истифодаи навори чистаро барои парвариши нӯхӯд, усуле донишмандона барои зиёд кардани самаранокии об ва дастӣ ба як <strong>миқдори хароҷоти нӯхӯд дар ҳектар бо чистаро</strong> Баландтар аст. Бо риояи масофаи мувофиқи ғироркунӣ, тарҳи дақиқи обёрӣ ва идоракунии таравшавӣ, мумкин аст умед дошта шавад, ки ҳосили ниҳоӣ нисбат ба обёрии ғарқобӣ 20 то 30 фоиз зиёд мешавад. Калиди муваффақият тоқат ва назорати мунтазам мебошад. Бо дарнаظгир кардани ин принсипҳо, соҳибкории шумо на танҳо аз ҷиҳати иқтисодӣ фойданоктар мешавад, балки ба ҳифзи манбаъҳои об низ мусоидат мекунад.</p>\n<p><strong>Маводи марбут:</strong> <a href="https://navar-abyari.ir/%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%DA%A9%D8%B1%D9%81%D8%B3/">D986D988D8A7D8B1 D8AADB8CD9BE DAA9D8B1D981D8B3</a>، <a href="https://navar-abyari.ir/%d8%ae%d8%b5%d9%88%d8%b5%db%8c%d8%a7%d8%aa-%d9%88-%d9%88%db%8c%da%98%da%af%db%8c%d9%87%d8%a7%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be/">Хусусиятҳои нӯри тири ва хусусишавии он</a>، <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d9%be%db%8c%d8%a7%d8%b2%da%86%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми ҳосилгирии пиёзача дар гектар: Рӯҳнамои мукаммал + нуқтаҳои афзоиш</a>، <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%da%a9%d9%86%d8%ac%d8%af-%d8%af%d8%b1-%d9%87%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори биёзони кунҷит дар гектар + нуқтаҳои афзоиши ҳосил</a></p>','Мавҷудоти нӯҳут дар гектар бо системаи нӯҳут: Раҳнамои амалӣ барои афзоиши меҳнат','Ошноӣ бо усулҳои бозрасии обёршавии нави тупи барои зиёд кардани ҳаҷми ғалляки шатхӯр дар як гектар. Ин роҳнамоиҳо нуқтаҳои амалии бӯдани дарахтон, идоракунии баргҳо ва ҷадвали бозрасии обёршавиро дар бар мегирад.','publish','closed','closed','navard-nohut-hektar-nihod-nivok-tape',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
