INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Мақоми тавсияшудаи фарқияти байни ҷунтҳои навриси хурӯҷонӣ дар ғалладориро тафтиш кунед, то ҳосили хурӯҷони хуби шояд гиред. Пешниҳодҳои техникӣ оид ба андозаи ҷунтҳо, андозаи ҷунтҳо ва ғунҷоиши ғунҷоӣ аз ҷониби AFP таҳия шудааст.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
