INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақола шумо мефаҳмед, ки чӣ қадар миқдори ғалла лозим аст барои 1 гектар. Ин дастурамал муфид барои қушзорҳо аст, то ҳосили беҳтар даст оварда, хизматнамоии бештар кунанд.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
