INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақола, мо шуморо бо ҷиҳати техникӣ маълум мекунам, ки қадаре бехи раггиб дар як гектар барои фаъолати дараҷаи баланд зарур аст. Ҳамчунин, мо нотиқ мегардаем, ки чӣ суръати парвариши раггиб дар соиши зиръатчиҳое, ки ба ин маҳсул таваҷҷуҳ доранд, омор дорад.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
