INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'rank_math_focus_keyword','Teejet Nozzle Spacing in Quinoa Cultivation: Recommended Standards' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='rank_math_focus_keyword');
INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррарот: Аҳамияти интихоби дурусти масофа дар парвариши қинуа</h2><p>Қинуа ҳамчун яке аз доннокиҳои камоборо, ки ба муҳити эҳтимоли коҳиш об бардошта мебошад, тадриҷан ҷойи худро дар системаҳои парвариши пайдарпаӣ дар Ҷумҳурии Исландӣ пайдо кардааст. Ин маҳсулот, гарчанде ки дараҷаи биёгузароии баланд дорад ва арзиши ғизоии баланд дорад, хеле ҳассос ба шароити обӣ ва миқдори роҳҳо мебошад. Дар шароит, ки роҳҳои кофӣ вуҷуд надорад, системаҳои обёрӣ бо фишор, бо номи бандҳои пухт, тарофияи ноил ба нигоҳ доштани ҳосил ва сифати донҳо мебошад.</p><p>Яке аз муҳимтарин мушкилоти техникии парвариши қинуа муайян кардани <strong>масофаи дурусти бандҳои пухт</strong> ҳисоб мешавад. Ин масофа на танҳо масофаи физикӣ байни хатҳои парваришро, балки дарозии ҷойгиршавии банд нисбат ба сатҳи хокро низ дар бар мегирад. Муайян кардани нодурусти ин масофаҳо метавонад ба ошобҳангӣ, ғайриодатнокшавии рушди решаҳо ва кам шудани ҳосилоти маҳсулот оварда расонад. Дар ин роҳнамо, мо дар бораи параметрҳои техникаӣ барои беҳтар кардани ҷойгиршавии бандҳои пухт дар заминҳои қинуа мебаррем.</p><h3>Чаро қинуа ба тақсимоти дақиқ масофаҳо ниёз дорад?</h3><p>Решаҳои қинуа нисбат ба гудумҳои анъанавӣ паҳншавии амудӣ ва уфуқии гузорошударо доранд. Ин доннок, одатан, дар системаҳои парвариши хори дар амикии кампакс пайдо мешавад. Ҳамин тавр, агар банди пухт аз банди тухм ба таври хеле дур ҷойгир бошад, қисме аз хок дар миёна бошиқ мемонад ва решаҳои шубо ба об дастрасӣ надоранд. Дар баракси, агар масофа хеле кам бошад, арзиши банди пухт дар ҳар гектар зиёд мешавад ва имконияти пайдо шудани намии иловагӣ ва рушди коҳҳорокиҳо дар пойи бурутаҳо баланд мешавад.</p><><h2>Андозаҳои муайян кардани масофа байни хатҳо (Масофаи байни хатҳо)</h2><p>Муайян кардани масофа байни сатҳҳои қиноа қади аввалин дар тарҳрезии системаи рибаи тиб будааст. Ин масофа ба ҳаҷми талаботи об, миқдори рӯшноӣ ба намудҳо ва дастрасӣ ба таҷҳизоти обварӣ таъсир мерасонад.</p><h3>Масофаи стандартӣ байни сатҳҳо</h3><p>Бар асоси таҷрибаҳои амалӣ дар минтаҳои шимолӣ ва марказии Эрон, масофаи бехатар барои сатҳҳои қиноа одатан байни 50 то 60 сантиметр муқаррар мешавад. Ин масофа ба намудҳо имкон медиҳад, ки то вақти пухтӣ фазои кофӣ барои паҳншавии олакҳо ва офтобгузиштарӣ ҳосил кунанд. Бо назардошти ин масофа, дар ҳар метр дарозии риба ду намуди қиноа ташкил мешавад ва системаи обварӣ бо таърифи мувофиқ рибаҳои 16 то 20 миллиметрро комилан пӯшонида мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-کینوا-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت کینوا: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop қиноа</figcaption></figure><p>Агар аз бадииҳои бунёртар истифода шавад ва масофа байни намудҳо дар дохили сатҳ ба камтар аз 30 сантиметр расад, масофа байни сатҳҳо бояд то 70 сантиметр зиёд карда шавад, то аз зиёдшавии олакҳо ва пастшавии бодгирии байни решаҳо ҳифз карда шавад. Ин нукта барои гирифтани дунбоҳои шитобзурби хеле муҳим аст.</p><h3>Таъсири чуқурии ҷойгиршавии риба ба масофа</h3><p>Чуқурии рибаи тиб бояд бевосита бо чуқурии паҳншавии решаи асосии қиноа мувофиқат кунад. Чуқурии идеалии риба одатан 10 то 15 сантиметр зер сатҳи хок мебошад. Агар чуқурии риба аз 15 сантиметр бештар шавад, решаҳои сатҳии қиноа дар оғози афзоиш об гиранда наметавонанд ва растаҳо дар одашавӣ меоранд. Аз ҷониби дигар, агар чуқурӣ камтар аз 5 сантиметр бошад, риба дар рӯйи офтоб ва вайроншавии механикӣ қарор мегирад. Бинобар ин, танзими дақиқи чуқурӣ дар тарафи масофаи уфуқӣ, калиди мувозинат дар системаи обварии қиноа аст.</p><><h2>Муайян кардани таъриф ва намуди рибаи тиб бар асоси масофа</h2><p>Пас аз муайян кардани масофа байни сатҳҳо, бояд навъи шланги тиббиро интихоб кунед. Масофаҳои тӯлоқтар лозим ба шлангҳо бо сарфи баландтар ё ҷойгиршавии ками сӯрохиҳои барорӣ доранд.</p><ul><li><strong>Шланги 16 миллиметрӣ:</strong> Барои масофаи сатҳҳои 50 то 60 сантиметр тавсия дода мешавад. Ин шлангҳо дар сарфҳои 1/5 то 2/0 литр ба соат пӯшиши мувофиқро эҷод мекунанд.</li><li><strong>Шланги 19 ё 20 миллиметрӣ:</strong> Агар масофаи сатҳҳо ба 70 то 80 сантиметр расад, аз ин ғафс истифода баред, то аз пайдоиши ғарҳҳои хушк дар маркази сатҳ пешгирӣ шавад.</li></ul><p>Бештарин масофа байни хориҷаҳои об дар шланги тибб бояд чунин бошад, ки дағаллҳои тар нигаронида шаванд. Барои кинва, ки решаҳои сатҳӣ дорад, нигарониши 15 то 20 фоизӣ дар шлангҳои 16 миллиметрӣ бо одамҳои рӯзона обкорӣ беҳтарин натиҷаро медиҳад.</p><h2>Огоҳиҳои амалӣ дар иҷрои системаи шланги тибб барои кинва</h2><p>Иҷрои дурусти системаи шланги тибб ба дақиқӣ дар ҷузъиёти хурд ниёз дорад. Бидуққатӣ дар пайваст кардани шланг ба шланги асосӣ ё ҳангоми корронии барг метавонад хароҷоти зиёдро ба бор орад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-کینوا-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت کینوا: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>Фазоилияти чизири дароҳайи чинукунӣ барои парҳозҳои кинуа</figcaption></figure><h3>Вақтебарҳакуниҳои парҳоз кардани тоҳук ва ҷобаҳову дохили чизири чинукунӣ</h3><p>Ҳар вақт таҳмилро ба чизири чинукунӣ 24 то 48 соат пеш аз парҳози тоҳук дар замин ба қабат дохил кунед. Агар таҳмил якгоҳ бо парҳози тоҳук гузаронида шавад, эҳтимоли тӯр пайдо кардани таҳмил ва ворид шудани хурак ба сӯрохиҳои чизири чинукунӣ вуҷуд дорад. Шумо инчунин метавонед, дар ғунӯни парҳоз, ба ғунӯни пӯсои таҳмил ба замин барои хушк кардан бадони парҳоз гузаронед. Ин кор фоизҳои рӯшниси тоҳукҳои кинуаро зиёд мекунад.</p><h3>Диққат ба шудагунии замин</h3><p>Дар замини шудагу, таҳмилҳо бояд дар равонаи амудии шудагу гузаронида шаванд, то об ба як тараф ҷамъ нашавад. Агар фазои сатҳҳои парҳоз 60 сантиметр бошад, дар шудагуҳои зиёздтар аз 5 фоиз, эҳтимоли ҷамъ омадани об дар сатҳҳои поёнӣ вуҷуд дорад. Дар ин ҳолат, истифодаи таҳмилҳо бо сӯрохиҳои бийометрикӣ ё чизири камкунанда метавонад мушкилро ҳал кунад.</p><p>Инчунин, ҳатман аз нӯсхаҳои пеш аз хариду таҳмил истифода кунед ва аз навири плейтетилен бо антиоксиданти қобил (таҳмили 3 солона) фоида бароред, зеро кинуа баъзан дар ду солаи агрӣ парҳоз карда мешавад ва мубориза бо тағйирот дар химияи таҳмил муҳим аст.</p><h2>Саволҳои мулоими дар бораи фазои таҳмил дар кинуа</h2><h3>Оё фазои таҳмил барои кинуа бо задукашак якхела аст?</h3><p>Не. Рӯгиёни қабри чурупъ (корни кукурузы) чурагъ аст ва умуманъ фаракат байни сатҳаҳои чурупъ 80 то 90 сантиметръ аст. Барои квинъа, фаракат 50 то 65 сантиметръ беътар аст, зероъ ки рӯгиёни онъ сатҳӣтар ва ҳассостар ба фишори об аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-کینوا-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت کینوا: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>drip tape spacing row layout crop квинъа</figcaption></figure><h3>Агар байни ду сатҳи навор хушкӣ дида шавад, чӣ кор кардан мумкин аст?</h3><p>Агар дар фаракати байни ду сатҳи навор хушкӣ дида шавад, ба ҷои илова кардани наворҳои паҳлӯӣ, басомади ороиро зиёд кунед ё аз наворҳое бо даби баландтар истифода баред. Рӯгиёни квинъа табииан кӯшиш мекунад ба самти сатҳҳои ҳосили ҳамсоя ҳаракат кунад, аммо ин баъдэ вақт мехонад.</p><h3>Оё фаракатҳои камтар аз 40 сантиметръ барои квинъа мумкин аст?</h3><p>Масъул намешаванд. Дар фаракатҳои камтар аз 40 сантиметръ, ошкороти нохтаҳо бо ҳам даргир шуда, ҳавою барор байни рӯгиён кам мешавад. Инчунин, хатарии биморшавӣ аз бемориҳои қашқъадор дар поёни нохта баланд мешавад ва доступ барои куштани ҳашорот душвор мешавад.</p><h2>Хулоса</h2><p>Оптимизатсияи фаракати навори чип дар квинъа як раванди осон, аммо бисёр муҳим аст. риояи фаракати байни 50 то 70 сантиметръ барои сатҳҳо ва чуруи 10 то 15 сантиметръ барои навор, пояҳои асосӣ барои дар кинории ин афунин муваффик будан аст. Бо назардошти шароити бодор, навъи замин ва шаби замин, шумо метавонед аз ҳарозии об пешгирӣ шуда ва фаъолияти баландтар барои донҳои квинъа ба даст оред. Истифодаи донишҳои ихтисосӣ ва истифода аз маълумотҳои озмоишгоҳии мамолати шумо, ҳамеша як қадами бештар дар самти муваффикшавӣ дар ороии квинъа аст.</p>\n<p><strong>Моҳоварҳои вобаста:</strong> <a href="https://navar-abyari.ir/strawberry-yield-per-hectare-iraq/">strawberry yield per hectare iraq</a>, <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%B3%D9%88%D8%B1%DA%AF%D9%88%D9%85-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA D8B3D988D8B1DAAFD988D985 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>, <a href="https://navar-abyari.ir/%d8%b9%d9%85%d9%84%da%a9%d8%b1%d8%af-%d9%be%db%8c%d8%a7%d8%b2-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳосили бӯғаи барои ҳектар: роҳҳои зиёд намудани меҳор ва фоида</a>, <a href="https://navar-abyari.ir/%d9%87%d9%85%d9%87-%da%86%db%8c%d8%b2-%d8%af%d8%b1%d8%a8%d8%a7%d8%b1%d9%87-%d9%85%d8%b2%d8%a7%db%8c%d8%a7%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d9%be%d9%84%d8%a7%da%a9%d8%af%d8%a7%d8%b1/">Ҳамаи чизҳо дар бораи фоидаҳои навъи нӯқи рақамидашуда</a></p>','Фосилаи шизири қулла дар кинва: Муносибати таъиншуда','Қуinoa барои барои шароити иқлимии номувофақот ба нақшакашии дақиқ дар системаи обёрӣ ниёз дорад. Ин мақола таҳсил мекунад, ки танзими дурусти масофаи нӯри тиш дар парвариши қуinoa чӣ гуна ба паҳншавии реша, кам кардани ғабғабҳо ва андозаи ниҳоии бадан таъсир мерасонад. Бо мо дар санҷишони меъёрҳои донишварии масофагузории байни сатҳҳо ва ҷойгиршавии нӯри дар чуқурии замин ҳамроҳ бошед, то аз нест шудани манбаҳо пешгирӣ кунед. Дар асоси ин, сардориҳои амалӣ пеш аз харидан ва тести нӯри тиш низ таҳсил мешаванд.','publish','closed','closed','fosila-i-shiziri-qulla-dar-kinva-munsiibati-tayinshuda',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
